            </Text>
          </div>
          <Switch
            size="l"
            checked={theme === 'dark'}
            onUpdate={(checked) => onThemeChange(checked ? 'dark' : 'light')}
            aria-label="Переключить тёмную тему"
          />
        </div>
      </Card>
    </div>
  );
}

